steps.code:
# Let's fetch group details for all trip groups to get member emails
group_ids = [281, 274, 279, 275, 280, 276, 277, 278]
group_details = {}
for gid in group_ids:
    group = apis.splitwise.show_group(group_id=gid, access_token=splitwise_token)
    group_details[gid] = group
    print(f"Group {gid}: {group['name']}")
    for m in group['members']:
        print(f"  {m['name']} - {m['email']}")
    print("---")

