steps.code:
# Build a global name->email mapping from all group members
name_to_email = {}
for gid, group in group_details.items():
    for member in group['members']:
        name_to_email[member['name']] = member['email']

print("Name to email mapping:")
for name, email in name_to_email.items():
    print(f"{name}: {email}")

