steps.code:
# Let's parse all expenses from all notes and map them to groups.
import re

def parse_expense_line(line):
    m = re.match(r'^- (.+?) paid \$(\d+(?:\.\d+)?) for "(.+?)"\. Owed equally by (.+)\.$', line)
    if not m:
        return None
    payer = m.group(1)
    amount = float(m.group(2))
    description = m.group(3)
    debtors_str = m.group(4)
    debtors = [x.strip() for x in re.split(r',| and ', debtors_str) if x.strip()]
    return {
        'payer': payer,
        'amount': amount,
        'description': description,
        'debtors': debtors
    }

# Map note_id to group_id based on titles
note_to_group = {}
for nid, note in notes_content.items():
    title = note['title']
    for gid, group in group_details.items():
        if group['name'] == title:
            note_to_group[nid] = gid
            break

print("note_to_group:", note_to_group)

# Parse all expenses
all_expenses = []
for nid, note in notes_content.items():
    content = note['content']
    lines = content.split('\n')
    for line in lines:
        if line.startswith('- '):
            exp = parse_expense_line(line)
            if exp:
                exp['note_id'] = nid
                exp['group_id'] = note_to_group.get(nid)
                all_expenses.append(exp)

print(f"Total expenses parsed: {len(all_expenses)}")
for exp in all_expenses:
    print(exp)

